package httpapi

import (
	"embed"
	"net/http"
	"strconv"
	"strings"
)

// Generated by python/tools/export_go_api_docs.py. These immutable resources
// preserve the default Source schema/templates without a runtime Python dependency.
//
//go:embed docsassets/openapi.json docsassets/swagger.html docsassets/oauth2-redirect.html docsassets/redoc.html
var documentationResources embed.FS

type documentationResource struct {
	path      string
	filename  string
	mediaType string
}

var documentationRoutes = [...]documentationResource{
	{"/openapi.json", "openapi.json", "application/json"},
	{"/docs", "swagger.html", "text/html; charset=utf-8"},
	{"/docs/oauth2-redirect", "oauth2-redirect.html", "text/html; charset=utf-8"},
	{"/redoc", "redoc.html", "text/html; charset=utf-8"},
}

// Called after the common body cap and authentication admission. Documentation
// is protected exactly like other data routes; query credentials do not apply.
func (s *Server) serveDocumentation(w http.ResponseWriter, r *http.Request) bool {
	for _, resource := range documentationRoutes {
		if r.URL.Path == resource.path+"/" {
			target := *r.URL
			target.Path, target.RawPath = strings.TrimSuffix(target.Path, "/"), ""
			target.Host = r.Host
			if target.Scheme == "" {
				target.Scheme = "http"
				if r.TLS != nil {
					target.Scheme = "https"
				}
			}
			w.Header().Set("Location", target.String())
			w.Header().Set("Content-Length", "0")
			w.WriteHeader(http.StatusTemporaryRedirect)
			return true
		}
		if r.URL.Path != resource.path {
			continue
		}
		if r.Method != http.MethodGet && r.Method != http.MethodHead {
			w.Header().Set("Allow", "GET, HEAD")
			writeJSON(s, w, http.StatusMethodNotAllowed, ErrorResponse{"Method Not Allowed"})
			return true
		}
		data, err := documentationResources.ReadFile("docsassets/" + resource.filename)
		if err != nil {
			writeJSON(s, w, http.StatusInternalServerError, ErrorResponse{"documentation resource unavailable"})
			return true
		}
		w.Header().Set("Content-Type", resource.mediaType)
		w.Header().Set("Content-Length", strconv.Itoa(len(data)))
		w.WriteHeader(http.StatusOK)
		if r.Method != http.MethodHead {
			_, _ = w.Write(data)
		}
		return true
	}
	return false
}
